import{_ as o,o as t,c as a,ag as d}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"API e webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"pt/car-wash/api.md","filePath":"pt/car-wash/api.md"}'),c={name:"pt/car-wash/api.md"};function s(i,e,r,n,h,l){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="api-e-webhooks" tabindex="-1">API e webhooks <a class="header-anchor" href="#api-e-webhooks" aria-label="Permalink to &quot;API e webhooks&quot;">​</a></h1><h2 id="permissoes" tabindex="-1">Permissões <a class="header-anchor" href="#permissoes" aria-label="Permalink to &quot;Permissões&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Âmbito</th><th>Concede</th></tr></thead><tbody><tr><td><code>nay_car_wash.config</code></td><td><code>/nay:carwash</code> (editor de túneis) e as definições do Car Wash no <code>/nay</code>.</td></tr></tbody></table><p>Conceda-o por ACE ou por uma regra, consulte <a href="/pt/nay-lib/permissions">Permissões</a>.</p><h2 id="api-http" tabindex="-1">API HTTP <a class="header-anchor" href="#api-http" aria-label="Permalink to &quot;API HTTP&quot;">​</a></h2><p>Primeiro ative a API e crie um token, consulte <a href="/pt/nay-lib/api">API HTTP</a>. As rotas respondem <code>{ &quot;ok&quot;: true, &quot;data&quot;: ... }</code> e exigem <code>Authorization: Bearer &lt;token&gt;</code>.</p><table tabindex="0"><thead><tr><th>Método</th><th>Rota</th><th>Âmbito</th><th>Query</th><th>Dados</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_car_wash/v1/history</code></td><td><code>nay_car_wash.history.read</code></td><td><code>identifier</code>, <code>kind</code> (<code>tunnel</code> ou <code>manual</code>), <code>limit</code> (1 a 100, predefinição 20), <code>before</code> (id)</td><td><code>items</code> (<code>id</code>, <code>identifier</code>, <code>kind</code>, <code>location</code>, <code>program</code>, <code>price</code>, <code>time</code>), do mais recente para o mais antigo, e <code>next</code>: passe-o como <code>before</code> para obter a página seguinte.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/stats</code></td><td><code>nay_car_wash.stats.read</code></td><td><code>days</code> (1 a 31, predefinição 7), <code>utcOffset</code> (minutos, -720 a 840, predefinição: o relógio do servidor)</td><td><code>utcOffset</code> usado, <code>total</code>, <code>byDay</code> (todos os dias listados) e <code>byLocation</code>, cada um com <code>washes</code> e <code>revenue</code>.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/tunnels</code></td><td><code>nay_car_wash.tunnels.read</code></td><td></td><td><code>index</code>, <code>label</code>, <code>enabled</code>, <code>entry</code> de cada túnel.</td></tr></tbody></table><p>Exemplo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer nay_1_xxxxxxxx&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.example.com/nay_car_wash/v1/stats?days=7&quot;</span></span></code></pre></div><h2 id="eventos-de-webhook" tabindex="-1">Eventos de webhook <a class="header-anchor" href="#eventos-de-webhook" aria-label="Permalink to &quot;Eventos de webhook&quot;">​</a></h2><p>Escolha-os no separador <strong>Webhooks</strong> do <code>/nay</code>, consulte <a href="/pt/nay-lib/webhooks">Webhooks</a>.</p><table tabindex="0"><thead><tr><th>Evento</th><th>Quando</th><th>Dados</th></tr></thead><tbody><tr><td><code>nay_car_wash.wash</code></td><td>Uma lavagem no túnel é concluída.</td><td><code>player</code> (nome), <code>identifier</code>, <code>tunnel</code>, <code>program</code>, <code>price</code></td></tr><tr><td><code>nay_car_wash.manual</code></td><td>Uma sessão numa máquina de alta pressão termina.</td><td><code>player</code> (nome), <code>identifier</code>, <code>station</code>, <code>price</code></td></tr></tbody></table><p>Com um webhook do Discord, cada lavagem torna-se um embed no seu canal, no idioma do servidor.</p>',13)])])}const u=o(c,[["render",s]]);export{m as __pageData,u as default};
